  $hajson${"slug": "health-assessment", "title": "Health Assessment", "description": "This course prepares nursing students to collect, interpret, document, and communicate subjective and objective assessment data across the lifespan. Students develop patient-centered interviewing, physical examination, cultural and psychosocial assessment, functional assessment, clinical reasoning, documentation, escalation, and simulation-ready performance.", "topics": [{"id": "dfafc73d-6221-491f-9db3-d0172cdea846", "type": "topic", "title": "Foundations of health assessment, safety, and therapeutic presence", "description": "Build the purpose, ethics, infection control, patient safety, and relationship skills behind every assessment.", "children": [{"id": "854ed6dd-ddef-40e4-9b2f-e64a9fb85ec8", "type": "subtopic", "title": "Purpose and scope of nursing assessment", "description": "Students learn why assessment is the gateway to clinical judgment, prioritization, intervention, and evaluation.", "children": [{"id": "71641513-5bff-452e-861b-fe71486e2769", "type": "concept", "title": "Subjective and objective data"}, {"id": "2cf9408c-9006-4bf8-aa94-932754ff3010", "type": "concept", "title": "Screening versus focused assessment"}, {"id": "11b254f7-ea38-4b39-a22d-158b6ab87416", "type": "concept", "title": "Baseline, trend, and change-in-condition assessment"}]}, {"id": "6ad3ee3b-b12c-40d2-a797-425d6ad5132d", "type": "subtopic", "title": "Safety, infection control, and preparation", "description": "This subtopic grounds assessment in safe practice before any technique begins.", "children": [{"id": "14dec97b-622e-439c-a6e3-0316b62107aa", "type": "concept", "title": "Hand hygiene and standard precautions"}, {"id": "16db38b3-b353-4492-b791-0052ffd40191", "type": "concept", "title": "Equipment, environment, privacy, and patient identification"}, {"id": "52e7a803-a7c1-4183-b726-688b9d7a170a", "type": "concept", "title": "Chaperones, consent, and scope of practice"}]}, {"id": "35f80370-06fd-4