  data = $hajson${"slug": "health-assessment", "title": "Health Assessment", "description": "This course prepares nursing students to collect, interpret, document, and communicate subjective and objective assessment data across the lifespan. Students develop patient-centered interviewing, physical examination, cultural and psychosocial assessment, functional assessment, clinical reasoning, documentation, escalation, and simulation-ready performance.", "topics": [{"id": "dfafc73d-6221-491f-9db3-d0172cdea846", "type": "topic", "title": "Foundations of health assessment, safety, and therapeutic presence", "description": "Build the purpose, ethics, infection control, patient safety, and relationship skills behind every assessment.", "children": [{"id": "854ed6dd-ddef-40e4-9b2f-e64a9fb85ec8", "type": "subtopic", "title": "Purpose and scope of nursing assessment", "description": "Students learn why assessment is the gateway to clinical judgment, prioritization, intervention, and evaluation.", "children": [{"id": "71641513-5bff-452e-861b-fe71486e2769", "type": "concept", "title": "Subjective and objective data"}, {"id": "2cf9408c-9006-4bf8-aa94-932754ff3010", "type": "concept", "title": "Screening versus focused assessment"}, {"id": "11b254f7-ea38-4b39-a22d-158b6ab87416", "type": "concept", "title": "Baseline, trend, and change-in-condition assessment"}]}, {"id": "6ad3ee3b-b12c-40d2-a797-425d6ad5132d", "type": "subtopic", "title": "Safety, infection control, and preparation", "description": "This subtopic grounds assessment in safe practice before any technique begins.", "children": [{"id": "14dec97b-622e-439c-a6e3-0316b62107aa", "type": "concept", "title": "Hand hygiene and standard precautions"}, {"id": "16db38b3-b353-4492-b791-0052ffd40191", "type": "concept", "title": "Equipment, environment, privacy, and patient identification"}, {"id": "52e7a803-a7c1-4183-b726-688b9d7a170a", "type": "concept", "title": "Chaperones, consent, and scope of practice"}]}, {"id": "35f80370-06fd-494a-b63e-d2775fbe6bbe", "type": "subtopic", "title": "Therapeutic presence and professionalism", "description": "Students learn to use demeanor, language, and respect as assessment tools.", "children": [{"id": "797c300b-3f92-46be-892a-aad239d51e41", "type": "concept", "title": "Professional introduction and agenda setting"}, {"id": "a3a69482-1b3c-454e-ba2a-c7b2958f4bd3", "type": "concept", "title": "Comfort, dignity, and draping"}, {"id": "f13c2d9d-4347-45a7-93c0-ea62ecad9bbf", "type": "concept", "title": "Bias awareness, empathy, and trust"}]}]}, {"id": "9d99923f-194d-42ed-a30b-dc6aaa3a3b88", "type": "topic", "title": "Health history, interviewing, and subjective data collection", "description": "Elicit accurate, patient-centered histories through structured, culturally responsive, trauma-informed communication.", "children": [{"id": "0b4e2f63-eabb-4122-b11a-4ceeb00e4922", "type": "subtopic", "title": "Interview structure", "description": "Students learn to collect complete histories without losing the patient's story.", "children": [{"id": "e5797420-38ba-4ea6-a7ca-82f04f8f74f1", "type": "concept", "title": "Chief concern and history of present illness"}, {"id": "54d0e143-2f48-49f8-b38b-390819fc0615", "type": "concept", "title": "Past medical, surgical, medication, allergy, family, and social history"}, {"id": "032fa56f-407d-43cd-8d2f-136939120027", "type": "concept", "title": "Review of systems"}]}, {"id": "dc80b415-a423-4b7a-ad6c-b30c3568190b", "type": "subtopic", "title": "Communication techniques", "description": "This subtopic develops the practical behaviors that make histories accurate and humane.", "children": [{"id": "079f690d-79d8-4875-b6ce-2686f85cd303", "type": "concept", "title": "Open-ended questions and active listening"}, {"id": "6a9dfe08-9cd0-45d2-b433-63a27358924d", "type": "concept", "title": "Clarification, summarization, and teach-back"}, {"id": "178a1250-4b4a-4557-82f2-c4d39145e4a8", "type": "concept", "title": "Working with interpreters and communication barriers"}]}, {"id": "2f6bdd18-f36b-4e61-8bc9-683792a93003", "type": "subtopic", "title": "Sensitive and trauma-informed history", "description": "Students learn to ask difficult questions safely and respectfully.", "children": [{"id": "20d6bf15-03d5-4b08-b777-683d9eff9fc4", "type": "concept", "title": "Sexual, substance use, mental health, violence, and safety history"}, {"id": "9c12623e-b95a-4dd3-907c-c81de1d0004a", "type": "concept", "title": "Trauma-informed choice, control, and pacing"}, {"id": "8a17d503-e171-4ee0-b20b-a33128d6ebb8", "type": "concept", "title": "Confidentiality and mandated reporting boundaries"}]}]}, {"id": "26a88d2a-21b3-46d9-9191-94d5a84fc552", "type": "topic", "title": "General survey, vital signs, pain, and clinical measurement", "description": "Recognize baseline appearance, distress, vital sign patterns, pain, and early warning changes.", "children": [{"id": "36477c01-7053-43f4-aa95-eb83bac0d7a6", "type": "subtopic", "title": "General survey", "description": "Students learn to form a first clinical impression from appearance, behavior, mobility, and distress.", "children": [{"id": "8aac32fa-0e2a-4f18-bdd0-aea1a3e13539", "type": "concept", "title": "Level of consciousness and orientation"}, {"id": "c832d65b-d4b7-40a6-bce5-77cb45ba5e5b", "type": "concept", "title": "Body habitus, posture, hygiene, and affect"}, {"id": "25e31aca-2e97-48a7-a950-b366196766d4", "type": "concept", "title": "Signs of acute distress and immediate risk"}]}, {"id": "64c773f3-1af2-412f-abe4-036ccc642066", "type": "subtopic", "title": "Vital signs and measurement accuracy", "description": "This subtopic teaches how technique affects interpretation and escalation.", "children": [{"id": "b41d993e-de91-4b4e-b5d9-07e5eeeb4c37", "type": "concept", "title": "Temperature, pulse, respirations, blood pressure, SpO2"}, {"id": "01bd666d-3b2c-4ba7-b766-f2fa70676886", "type": "concept", "title": "Orthostatic vital signs and pain as an assessment domain"}, {"id